"""Local file storage for emails kept by the mail handler (refused, quarantined, complaints).

Files live under config.UPLOAD_DIR, which must not be served over HTTP: the stored
emails are private and there is no per-file access control.
"""

import os
from io import BytesIO

from app import config


def _full_path(path: str) -> str:
    root = os.path.realpath(config.UPLOAD_DIR)
    full_path = os.path.realpath(os.path.join(root, path))
    # paths are generated by us, but never allow escaping the storage dir
    if os.path.commonpath([root, full_path]) != root:
        raise ValueError(f"Invalid storage path {path}")
    return full_path


def upload_email_from_bytesio(path: str, bs: BytesIO, filename: str = ""):
    """Store an email. `filename` is kept for API compatibility with the old S3 backend."""
    bs.seek(0)
    full_path = _full_path(path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    with open(full_path, "wb") as f:
        f.write(bs.read())


def delete(path: str):
    full_path = _full_path(path)
    if os.path.exists(full_path):
        os.remove(full_path)
